    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
      color: var(--text);
      background:
        radial-gradient(circle at top, rgba(37, 99, 235, 0.14), transparent 38%),
        linear-gradient(180deg, #eef4ff 0%, var(--bg) 100%);
      min-height: 100vh;
      display: grid;
      place-items: center;
      padding: 32px 20px;
    }

    .support-card {
      width: min(100%, 680px);
      background: var(--panel);
      border: 1px solid rgba(215, 223, 234, 0.75);
      border-radius: calc(var(--radius) + 4px);
      box-shadow: var(--shadow);
      backdrop-filter: blur(14px);
      padding: 32px;
    }

    .eyebrow {
      margin: 0 0 8px;
      color: var(--accent);
      font-size: 0.875rem;
      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 0;
      font-size: clamp(2rem, 3vw, 2.6rem);
      line-height: 1.1;
    }

    .intro {
      margin: 12px 0 28px;
      color: var(--muted);
      max-width: 58ch;
      line-height: 1.6;
    }

    form {
      display: grid;
      gap: 18px;
    }

    .form-field {
      display: grid;
      gap: 8px;
    }

    label {
      font-weight: 600;
    }

    input {
      width: 100%;
      border: 1px solid var(--border);
      border-radius: 14px;
      padding: 14px 16px;
      font: inherit;
      color: var(--text);
      background: #fff;
      transition: border-color 150ms ease, box-shadow 150ms ease, transform 150ms ease;
    }

    input::placeholder {
      color: #94a3b8;
    }

    input:focus {
      outline: none;
      border-color: rgba(37, 99, 235, 0.8);
      box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.14);
    }

    input[aria-invalid="true"] {
      border-color: var(--error);
      box-shadow: 0 0 0 4px rgba(220, 38, 38, 0.1);
    }

    .help-text,
    .error-message {
      font-size: 0.92rem;
      line-height: 1.45;
    }

    .help-text {
      color: var(--muted);
    }

    .error-message {
      color: var(--error);
      min-height: 1.3em;
    }

    .actions {
      margin-top: 6px;
      display: flex;
      justify-content: flex-end;
    }

    button {
      border: 0;
      border-radius: 999px;
      padding: 14px 22px;
      font: inherit;
      font-weight: 700;
      color: #fff;
      background: linear-gradient(135deg, var(--accent), var(--accent-strong));
      box-shadow: 0 12px 30px rgba(37, 99, 235, 0.28);
      cursor: pointer;
      transition: transform 150ms ease, box-shadow 150ms ease, filter 150ms ease;
    }

    button:hover {
      transform: translateY(-1px);
      filter: brightness(1.02);
    }

    button:focus {
      outline: none;
      box-shadow: 0 0 0 4px rgba(37, 99, 235, 0.18), 0 12px 30px rgba(37, 99, 235, 0.28);
    }

    .success-message {
      margin: 16px 0 0;
      color: #166534;
      font-weight: 600;
      min-height: 1.5em;
    }

    @media (max-width: 560px) {
      .support-card {
        padding: 24px 18px;
      }

      .actions {
        justify-content: stretch;
      }

      button {
        width: 100%;
      }
    }
  </style>
